import{_ as d,o as r,c as a,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const b=JSON.parse('{"title":"大模型推荐角色（实验）","description":"","frontmatter":{"title":"大模型推荐角色（实验）","layout":"doc"},"headers":[],"relativePath":"site/zh/llm-recommend.md","filePath":"site/zh/llm-recommend.md"}'),e={name:"site/zh/llm-recommend.md"};function s(n,t,l,h,i,c){return r(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="大模型推荐角色" tabindex="-1">大模型推荐角色 <a class="header-anchor" href="#大模型推荐角色" aria-label="Permalink to &quot;大模型推荐角色&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">实验性内容</p><p>本页面由大模型（AI）<strong>独立推导</strong>生成：仅读取本站镜像的角色原始数据（370 名角色的 五维 / 必杀技 / 固有效果）与系统机制事实（伤害公式、intro、必杀连锁、装备规则），<strong>刻意不参考</strong>官方讨伐战强度榜、官方新手指南点名等任何攻略页推荐名单。推荐结论由&quot;机制稀缺度 × 公式独立乘区 × 站场能力 × 满突成本&quot;推导，仅供参考，持续修正。当前版本：v0.2（2026-07-29）</p></div><h2 id="推荐标准-一句话" tabindex="-1">推荐标准（一句话） <a class="header-anchor" href="#推荐标准-一句话" aria-label="Permalink to &quot;推荐标准（一句话）&quot;">​</a></h2><p><strong>机制稀缺度 × 公式独立乘区 × 站场能力 × 满突成本</strong>——不看出身、不看官方榜。</p><blockquote><p>满级五维高度收敛（攻击/魔法上限 521，体力上限 3200，防御上限 500），绝大多数 SSR 数值相同，<strong>数值不是区分度，固有效果才是</strong>。速度辅助(126人)/充能辅助(105人)/AoE(247人)属通胀技能，不当稀缺卖点。详见 <code>llm_reco/reco-method.md</code>、<code>reasoning-log.md</code>。</p></blockquote><h2 id="一、不撤退站场核心-最高权重-全游戏仅-8-人" tabindex="-1">一、不撤退站场核心（最高权重，全游戏仅 8 人） <a class="header-anchor" href="#一、不撤退站场核心-最高权重-全游戏仅-8-人" aria-label="Permalink to &quot;一、不撤退站场核心（最高权重，全游戏仅 8 人）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>推荐理由（核验要点）</th></tr></thead><tbody><tr><td>ビートソニック・アキレス</td><td>SSR</td><td>不撤退 + 血量&lt;20% 回 25~50% 体力(1次)，站场副坦</td></tr><tr><td>ブライドハルカ・リバース</td><td>SSR</td><td>不撤退 + 攻击 521(上限) + 10% 即死(失败叠攻上限50%)，攻防一体</td></tr><tr><td>真夏のハルカ</td><td>SSR</td><td>不撤退 + 必杀眩晕+50/防御+75/&lt;20%必杀+50</td></tr><tr><td>閃忍マユリ</td><td>R</td><td>不撤退 + 必杀 <strong>15× 无视防御</strong>(自承100%体力)，全游戏最暴力单体核弹，R 白送</td></tr><tr><td>FM77</td><td>R</td><td>不撤退（免费获取），零成本稀缺站场机制</td></tr><tr><td>神騎フローレル / 閃忍レイナ / 神騎プロキオン</td><td>R/SR</td><td>不撤退，低成本站场补位</td></tr></tbody></table><blockquote><p>新手优先满突 <strong>FM77 / 閃忍マユリ</strong>——用 R 卡成本拿到全游戏前 2% 的站场机制。</p></blockquote><h2 id="二、顶级稀缺对策-各仅-1-人-s-级必看" tabindex="-1">二、顶级稀缺对策（各仅 1 人，S 级必看） <a class="header-anchor" href="#二、顶级稀缺对策-各仅-1-人-s-级必看" aria-label="Permalink to &quot;二、顶级稀缺对策（各仅 1 人，S 级必看）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>推荐理由</th></tr></thead><tbody><tr><td>超昂閃忍ナリカ</td><td>SSR</td><td><strong>复活</strong>(火种) + 自然体力消耗停 25% + 双修 521/521/500，唯一复活位，泛用顶级</td></tr><tr><td>体育祭のヤブルー</td><td>SSR</td><td><strong>全异常免疫</strong>(独 1) + 出战全队必杀+25% + 必杀全体 50%魅惑/75%束缚，唯一真·全免控 + 巨型团队硬控</td></tr><tr><td>妹の1024</td><td>SSR</td><td>普攻 80% 概率友军必杀+10%(自身同步) + 必杀 场地速度+30%/全队必杀+30%(叠5次)，顶配充能核心</td></tr></tbody></table><h2 id="三、稀有增益辅助-攻击增益仅-3-人-魔法增益仅-1-人" tabindex="-1">三、稀有增益辅助（攻击增益仅 3 人，魔法增益仅 1 人） <a class="header-anchor" href="#三、稀有增益辅助-攻击增益仅-3-人-魔法增益仅-1-人" aria-label="Permalink to &quot;三、稀有增益辅助（攻击增益仅 3 人，魔法增益仅 1 人）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>推荐理由</th></tr></thead><tbody><tr><td>真夏のイーイー</td><td>SSR</td><td>在场友军出战攻击+30%(盛夏+50/速度+25) + 必杀横排 6×魔法 + 全队眩晕抵抗+50，攻击增益仅 3 人之一</td></tr><tr><td>黒門天・屍寺炎斎</td><td>SSR</td><td>&lt;30%/65% 双节点 每秒5%回血+防御+100% + 必杀 10×魔法(存活攻击+30%上限150%)，攻击增益仅 3 人之一</td></tr><tr><td>魔女ミヤビ</td><td>SSR</td><td>出战敌方防速−20%(+魔女人数×10%增幅)，罕见减益；（信号标记为稀有攻击/魔法增益持有者，具体幅度待全量核实）</td></tr></tbody></table><h2 id="四、免控领域-治疗-被动、无消耗-性价比最高的对策位" tabindex="-1">四、免控领域 + 治疗（被动、无消耗，性价比最高的对策位） <a class="header-anchor" href="#四、免控领域-治疗-被动、无消耗-性价比最高的对策位" aria-label="Permalink to &quot;四、免控领域 + 治疗（被动、无消耗，性价比最高的对策位）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>推荐理由</th></tr></thead><tbody><tr><td>制服ニャンコ</td><td>SSR</td><td>在场全队 毒·魅惑·束缚(+/眩晕)免疫 + 必杀自身回50%/全队回30%/全队输出+20%</td></tr><tr><td>閃忍ニャンコ</td><td>SSR</td><td>在场全队 毒·魅惑·束缚·眩晕 免疫 + 必杀单体友军回100%+攻防速+30%</td></tr><tr><td>魔女フタバ</td><td>R</td><td>在场全队 毒·魅惑·眩晕·束缚 免疫 + 必杀横排 6×魔法，R 卡全队免控领域</td></tr><tr><td>六の法杖セラフィール</td><td>SSR</td><td>出战<strong>清除全队异常/减益</strong>(+回15%) + 场地 5%/s 回血，极稀有被动解控治疗</td></tr><tr><td>ビートプレジデント・シーラ</td><td>SSR</td><td>普攻 15% 概率附加必中魅惑/束缚/输出−20 + 必杀全队 2.5%/s 回血</td></tr><tr><td>アイドルの奉輪こもり</td><td>SSR</td><td><strong>撤退时</strong>全队回 50% + 攻防+30%（死亡即全队大补）</td></tr><tr><td>魔女シズク</td><td>R</td><td>出战全队 1~2%/s 回血 + 必杀全体 2~4×物理 + 场地 2~3%/s 回血，廉价群疗</td></tr></tbody></table><h2 id="五、破防-减益-独立乘区-对高防-boss-暴涨" tabindex="-1">五、破防 / 减益（独立乘区，对高防 boss 暴涨） <a class="header-anchor" href="#五、破防-减益-独立乘区-对高防-boss-暴涨" aria-label="Permalink to &quot;五、破防 / 减益（独立乘区，对高防 boss 暴涨）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>推荐理由</th></tr></thead><tbody><tr><td>鬼の斗羽大洋</td><td>SSR</td><td>出战 敌方输出−25%/我方+25% + 必杀 <strong>全体攻防−60%</strong>，减益幅度罕见</td></tr><tr><td>神騎ハニーエル</td><td>R</td><td>自身魔法免疫 + 全队 眩晕·束缚 免疫 + 必杀穿透蜂蜜魔免，R 卡魔免对策专精</td></tr><tr><td>閃忍マユリ</td><td>R</td><td>见第一节：15× 无视防御核弹</td></tr></tbody></table><h2 id="六、硬控对策-r-卡廉价方案" tabindex="-1">六、硬控对策（R 卡廉价方案） <a class="header-anchor" href="#六、硬控对策-r-卡廉价方案" aria-label="Permalink to &quot;六、硬控对策（R 卡廉价方案）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>推荐理由</th></tr></thead><tbody><tr><td>エスカ・アメイズ</td><td>R</td><td>必杀 全体 <strong>必中魅惑</strong>(魅惑免疫除外)</td></tr><tr><td>閃忍クサリ</td><td>R</td><td>必杀 全体 <strong>强制眩晕</strong>(眩晕免疫除外) + 束缚 + 速度−20</td></tr><tr><td>閃忍ツルコ</td><td>R</td><td>出战自身速度+30 + 必杀全体 2~4×物理 + 眩晕+50</td></tr></tbody></table><h2 id="七、新手核心-低成本满突-按机制而非官方点名" tabindex="-1">七、新手核心（低成本满突，按机制而非官方点名） <a class="header-anchor" href="#七、新手核心-低成本满突-按机制而非官方点名" aria-label="Permalink to &quot;七、新手核心（低成本满突，按机制而非官方点名）&quot;">​</a></h2><blockquote><p>铁律：满突★5 的 R ≫ 零突★1 的 SSR。下列为机制稀缺且易满突的 R/SR 起步底盘（已替换 v0.1 中未核验的&quot;官方点名&quot;卡）：</p></blockquote><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>承担机制</th></tr></thead><tbody><tr><td>FM77</td><td>R</td><td>不撤退（免费）</td></tr><tr><td>閃忍マユリ</td><td>R</td><td>不撤退 + 15× 无视防御核弹</td></tr><tr><td>神騎アルゴル</td><td>R</td><td>出战场地速度+25% + 必杀全队必杀+30%</td></tr><tr><td>神騎ハニーエル</td><td>R</td><td>魔法免疫 + 全队眩晕/束缚免疫 + 破魔免</td></tr><tr><td>閃忍サイカ</td><td>R</td><td>出战<strong>敌方时停 2.5~4s</strong>(独一份开局冻结) + 低速3人速度+25%</td></tr><tr><td>魔女シズク</td><td>R</td><td>廉价群体治疗</td></tr><tr><td>エスカ・アメイズ</td><td>R</td><td>必中魅惑</td></tr><tr><td>閃忍クサリ</td><td>R</td><td>强制眩晕</td></tr><tr><td>魔女フタバ</td><td>R</td><td>全队 4 异常免疫领域</td></tr><tr><td>ビートアミュレット・ノノノ</td><td>R</td><td>出战全队必杀+25% + 必杀全队攻防+30/敌方−30</td></tr></tbody></table><h2 id="八、体系核心-阵营增益轴" tabindex="-1">八、体系核心（阵营增益轴） <a class="header-anchor" href="#八、体系核心-阵营增益轴" aria-label="Permalink to &quot;八、体系核心（阵营增益轴）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阵营</th><th>增益核心</th><th>说明</th></tr></thead><tbody><tr><td>魔女</td><td>魔女シズク(R) / 魔女ミヤビ</td><td>R 卡即体系核心的稀缺例</td></tr><tr><td>战士</td><td>エスカレイヤー 系</td><td>传说战士+：开幕对 3 名战士施加强力增益（幅度待全量核实）</td></tr><tr><td>闪忍</td><td>閃忍ハルカ / 閃忍サイカ(对彼岸花+300%)</td><td>闪忍增益 + 速度轴</td></tr><tr><td>神骑</td><td>神騎エクシール / 神騎アルゴル(R)</td><td>神骑增益 + 廉价充能</td></tr></tbody></table><hr><h2 id="九、配队与副本对策-v0-3-增补" tabindex="-1">九、配队与副本对策（v0.3 增补） <a class="header-anchor" href="#九、配队与副本对策-v0-3-增补" aria-label="Permalink to &quot;九、配队与副本对策（v0.3 增补）&quot;">​</a></h2><blockquote><p>结合讨伐战/副本机制与编队接力系统（事实数据，非推荐榜）。详细方案见 <code>llm_reco/reco-team.md</code>。</p></blockquote><h3 id="关键认知-上场-5-人-单队决战" tabindex="-1">关键认知：上场 5 人 ≠ 单队决战 <a class="header-anchor" href="#关键认知-上场-5-人-单队决战" aria-label="Permalink to &quot;关键认知：上场 5 人 ≠ 单队决战&quot;">​</a></h3><p>讨伐战体力每秒扣 2%（百分比、<strong>双防无效</strong>），单队约 50 秒必退 → 高分靠<strong>多队接力</strong>：优先1(5)→优先2(15)→替补→星面50人。&quot;分队伍&quot;=接力轮换，故配队需给&quot;首发队+接力队&quot;结构。</p><h3 id="配队铁律" tabindex="-1">配队铁律 <a class="header-anchor" href="#配队铁律" aria-label="Permalink to &quot;配队铁律&quot;">​</a></h3><ul><li><strong>降防 debuff &gt;&gt; 攻击 buff</strong>：75% 减伤 BOSS 时降防收益是攻 buff 的 <strong>3 倍</strong>。优先把减伤降低堆到 80%+。</li><li>单体 + 领域同名<strong>叠加</strong>；同类多角色同款只取最高。</li><li>必杀<strong>充能辅助=得分核心</strong>；默认带<strong>持续治疗</strong>；<strong>确定点灯（BREAK）比时停更值</strong>。</li></ul><h3 id="通用-5-人首发模板" tabindex="-1">通用 5 人首发模板 <a class="header-anchor" href="#通用-5-人首发模板" aria-label="Permalink to &quot;通用 5 人首发模板&quot;">​</a></h3><p>主输出（ブライドハルカ/O闪忍奈理卡/閃忍マユリ R）+ 生存辅助（ビートアミュレット・ノノノ R/神騎アルゴル R）+ 降防手（鬼の斗羽大洋 SSR/魔女ミヤビ）+ 治疗（制服ニャンコ/六の法杖セラフィール/魔女シズク R）+ 自由位（妹の1024 SSR/真夏のイーイー）。</p><h3 id="七大-boss-对策要点" tabindex="-1">七大 BOSS 对策要点 <a class="header-anchor" href="#七大-boss-对策要点" aria-label="Permalink to &quot;七大 BOSS 对策要点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>BOSS</th><th>必需对策</th><th>推荐角色（已核验）</th></tr></thead><tbody><tr><td>古纳冈</td><td>持续治疗（领域1%/s）</td><td>制服ニャンコ / 六の法杖セラフィール</td></tr><tr><td>乌塔尔</td><td>全体攻击/异常必杀清小猫</td><td>体育祭のヤブルー（全体魅惑+束缚）</td></tr><tr><td>堕威大佛</td><td>确定点灯（无视抗）</td><td>エスカ・アメイズ R（必中魅惑）/ 閃忍クサリ R（强制眩晕）</td></tr><tr><td>大往女</td><td>束缚免疫/解控</td><td>制服ニャンコ / 魔女フタバ R / 神騎ハニーエル R</td></tr><tr><td>弗栗多</td><td>减速+破盾+居座</td><td>减速角色（闪忍/魔女系）+ 超昂奈理卡（体力停25%）</td></tr><tr><td>黄金甜心</td><td>物理队 / 咬甜心王子装备</td><td>物理输出为主</td></tr><tr><td>狂王</td><td>全体必杀清随从</td><td>全体 AoE 输出</td></tr></tbody></table><h3 id="从-370-人挑-5-人均衡队的方法-v0-4" tabindex="-1">从 370 人挑 5 人均衡队的方法（v0.4） <a class="header-anchor" href="#从-370-人挑-5-人均衡队的方法-v0-4" aria-label="Permalink to &quot;从 370 人挑 5 人均衡队的方法（v0.4）&quot;">​</a></h3><p>5 框要塞下&quot;输出+降防+速度+充能+治疗(生存)&quot;最少 5 职能；若每人单职需 ≥6 槽 &gt; 上限，<strong>唯一解=挑一人兼多职的高密度卡</strong>（对 <code>char_data.json</code> 全量打职能标签后实测：≥3 职 46 人、≥4 职 37 人、≥5 职 10 人）。</p><ul><li><strong>真正稀缺、优先占槽的职能</strong>：不撤退(8)/复活(1,全游戏唯 O闪忍奈理卡)/降防(46)。</li><li><strong>用户强调的速度(126)/充能(102)持有量充足</strong>，不必占独立槽——专挑&quot;顺带兼速度/充能&quot;的高密度卡即可。</li><li><strong>顶配均衡队</strong>：エスカサファイア・ムーンライズ(输出+速度+增伤) + 小鬼の斗羽大洋(降防+治疗+免疫,单卡顶4职) + ダンスクイーン・ピカ(充能+速度) + O闪忍奈理卡(复活) + FM77(不撤退)。</li><li><strong>新手 R/SR 队</strong>：ビートノーブル・カノン(R) + 閃忍フクシュウチャン(SR) + ビートアミュレット・ノノノ(R) + FM77(R) + ビートアイドル・タマキ(R)——仅 R/SR 也 5/5 覆盖。</li><li>详细方法论与 4 套队伍逐槽职能见 <code>llm_reco/reco-team.md</code> 2b 节。</li></ul><h3 id="量化强度模型-v0-8-raid-专用-·-真实频率公式-·-真实觉醒表-·-真实两件配装-·-考试式打分" tabindex="-1">量化强度模型 v0.8（RAID 专用 · 真实频率公式 · 真实觉醒表 · 真实两件配装 · 考试式打分） <a class="header-anchor" href="#量化强度模型-v0-8-raid-专用-·-真实频率公式-·-真实觉醒表-·-真实两件配装-·-考试式打分" aria-label="Permalink to &quot;量化强度模型 v0.8（RAID 专用 · 真实频率公式 · 真实觉醒表 · 真实两件配装 · 考试式打分）&quot;">​</a></h3><p>默认满星培养 → <strong>单角色强度是固定值</strong>，可建数学模型；推荐时直接算出&quot;能打多少伤害、施加多少 buff/debuff&quot;。终局副本 4 种（raid / B宇宙 / 广域战 / 全域战），<strong>本模型只攻破 raid</strong>，其余三模式先占位。为建通用模型，把除「角色 kit + 真实战斗细节」外的一切<strong>全固定为常数</strong>（R=0.50 / 连击阈值60% / <strong>觉醒属性强化按游戏真实表</strong> / <strong>装备按真实两件配装</strong>）：</p><ul><li><strong>BOSS 固定</strong>：机制常亮 · 固定伤害 · 体力 -2%/s · 固定防御率 R=0.50（古纳冈类）</li><li><strong>角色固定</strong>：满星100级 · 觉醒+ · 觉醒属性强化满 · <strong>两件主装：火箭(行动速度-50%)+腰带(攻魔+50%)</strong>（副装贴片/纳豆不计——多变量，纳豆还与部分角色技能冲突）</li><li><strong>觉醒属性强化（真实表）</strong>：行动速度 <strong>-0.1×20次=最多-2秒（扁平），强化下限 3sec</strong>（基础已≤3s 零收益）；必杀充能 <strong>+0.3×20次=最多+6pt，强化上限 15%</strong>（基础≥15 零收益）；攻/魔 +20%。上限 3s/15% 非人人可达——强化次数有限。</li><li><strong>真实战斗细节</strong>（extract_chars.py 抽 詳細ステータス）：行動速度(sec) / 必殺充填量(%) / 連撃率(%)</li></ul><p><strong>单角色强度分</strong> = <code>0.70·DPS归一 + 0.30·UTIL归一</code>，DPS 用真实频率算（分数=秒伤）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>eff_speed   = max(行動速度 - 2, 3)              # 觉醒扁平减秒，下限3sec</span></span>
<span class="line"><span>interval     = eff_speed × (1 - 火箭50%)</span></span>
<span class="line"><span>interval_ult= interval × (1 + 連撃率)          # 连击拖慢必杀/普攻节奏（连击惩罚）</span></span>
<span class="line"><span>充能eff     = 充≥15 ? 原值 : min(充+6, 15)      # 觉醒+6pt上限15%</span></span>
<span class="line"><span>必杀casts/s = (充能eff/100) / interval_ult</span></span>
<span class="line"><span>combo_mult  = 1 + Σ連撃率ⁿ×decay(n)            # 连击追加伤害(不暴击)</span></span>
<span class="line"><span>削减系数    = 1 - 0.50×(1 - min(1, 降防))       # 降防只剩角色 kit 自带（§7.6）</span></span>
<span class="line"><span>基础单击    = 攻魔×1.20 × (1 + 攻buff + 腰带50%) × (1+增伤) × 削减系数</span></span>
<span class="line"><span>DPS = 基础单击×必杀倍率×3×击破×必杀casts/s  +  (基础单击·暴击 + 基础单击·(combo_mult-1))×普攻频率</span></span>
<span class="line"><span>UTIL = 100·复活 + 60·不撤退 + 40·免疫 + 35·奶 + 30·解控 + 25·硬控 + 30·减伤%</span></span></code></pre></div><p>→ 按分值分 <strong>T0/T1/T2/T3</strong>（T0 共37人，SSR35/SR1/R1）；370 人实跑 TOP：<strong>レジェンド・ハルカ 78.9 &gt; 幻忍コテツ 75.4 &gt; 黒門天 73.0 &gt; ブライド・スバル 61.3 &gt; 真夏のハルカ 55.3</strong>——装备不再送 30% 降防打底后，<strong>kit 自带降防价值暴涨</strong>（降防100% vs 60% = 削减系数 1.00 vs 0.80 = 25% 伤害差，直接改写头名）。<strong>連撃验证</strong>：连击率≥60% 仅 3 人，バビロニア・ニル 必杀占比仅 13.1%（普攻≫必杀），确证「连击型必杀权重下降」。 <strong>队伍考试打分</strong>（4 队·固定场景+7BOSS 适配）：综合平均 <strong>D暴力输出 42,281 &gt; C居座 16,529 &gt; A顶配 12,541 &gt; B新手 7,344</strong>（D 为 5 纯输出降防100%×9~×10 → 完全免削减，raw DPS 46,979 碾压，但缺全体→乌塔尔/狂王 fit 0.60/0.70 扣分）。 模型与完整验证见 <code>llm_reco/reco-team.md</code> §5 与 <code>reasoning-log.md</code> §9；脚本 <code>llm_reco/_char_score.py</code>，新增角色补进 <code>char_data.json</code> 重跑即出分。</p><blockquote><p>副本维度：主线/EX 有<strong>时间限制、双防有效</strong> → 不撤退/复活（O闪忍奈理卡、B索尼克・阿基里斯）此处才是真神；每日/宝箱狩猎效率优先用 AoE+充能。</p></blockquote><hr><p><em>本页为 AI 独立实验页面，尚未收录进站点导航。修订记录：v0.1（2026-07-28，受官方榜影响）；v0.2（2026-07-29，脱离官方榜、基于角色数据与机制推导）；v0.3（2026-07-29，结合副本/BOSS 与配队接力）。完整推理见 <code>llm_reco/reasoning-log.md</code> 与 <code>reco-team.md</code>。</em></p>`,46)])])}const p=d(e,[["render",s]]);export{b as __pageData,p as default};
